#include <vector>

typedef unsigned short wedge_ref;
typedef unsigned face_ref;

class wedge_split
{
public:
    wedge_split(const wedge_split&);

    wedge_ref old_wedge_id;
    wedge_ref new_wedge_id;
    vector<face_ref> faces_for_split;
};

wedge_split::wedge_split(const wedge_split& split) :
    old_wedge_id(split.old_wedge_id),
    new_wedge_id(split.new_wedge_id),
    faces_for_split(split.faces_for_split)
{
}
